def solve(s):
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            toks.append(int(s[i:j]))
            i = j
        else:
            toks.append(c)
            i += 1
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def take():
        t = toks[pos[0]]
        pos[0] += 1
        return t

    def expr():
        v = term()
        while peek() in ('+', '-'):
            op = take()
            r = term()
            v = v + r if op == '+' else v - r
        return v

    def term():
        v = unary()
        while peek() in ('*', '/'):
            op = take()
            r = unary()
            v = v * r if op == '*' else v // r
        return v

    def unary():
        if peek() == '-':
            take()
            return -unary()
        if peek() == '+':
            take()
            return unary()
        return atom()

    def atom():
        t = take()
        if t == '(':
            v = expr()
            take()
            return v
        return t

    return expr()

from collections import Counter

def solve(text, k):
    counts = Counter()
    for w in text.split():
        w = w.lower().strip('.,!?;:')
        if w:
            counts[w] += 1
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return "\n".join(f"{w} {c}" for w, c in items[:k])

def solve(text):
    stats = {}
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        level = parts[0]
        rest = parts[1] if len(parts) > 1 else ""
        comp = rest.split(":", 1)[0].strip()
        e, w = stats.get(comp, (0, 0))
        if level == "ERROR":
            e += 1
        elif level == "WARN":
            w += 1
        stats[comp] = (e, w)
    items = sorted(stats.items(), key=lambda kv: (-kv[1][0], -kv[1][1], kv[0]))
    return "\n".join(f"{c} {e} {w}" for c, (e, w) in items)

LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def winner(b):
    for a, c, d in LINES:
        if b[a] != '.' and b[a] == b[c] == b[d]:
            return b[a]
    return None

def value(b, player, me):
    # outcome from me's perspective: 1 win, 0 draw, -1 loss; player to move
    w = winner(b)
    if w is not None:
        return 1 if w == me else -1
    if '.' not in b:
        return 0
    best = None
    for i in range(9):
        if b[i] == '.':
            b[i] = player
            v = value(b, 'O' if player == 'X' else 'X', me)
            b[i] = '.'
            if player == me:
                if best is None or v > best:
                    best = v
                if best == 1:
                    break
            else:
                if best is None or v < best:
                    best = v
                if best == -1:
                    break
    return best

def solve(board, side):
    b = list(board.strip())
    other = 'O' if side == 'X' else 'X'
    best_i, best_v = None, None
    for i in range(9):
        if b[i] == '.':
            b[i] = side
            v = value(b, other, side)
            b[i] = '.'
            if best_v is None or v > best_v:
                best_i, best_v = i, v
    return best_i

