def solve(s):
    nums = [int(x) for x in s.split()]
    ivs = []
    for i in range(0, len(nums), 2):
        a, b = nums[i], nums[i+1]
        ivs.append((min(a, b), max(a, b)))
    ivs.sort()
    merged = []
    for lo, hi in ivs:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1] = (merged[-1][0], hi)
        else:
            merged.append((lo, hi))
    return " ".join(f"{lo}-{hi}" for lo, hi in merged)

import heapq

def solve(edges, start, goal):
    adj = {}
    for tok in edges.split():
        ab, w = tok.split(":")
        a, b = ab.split("-")
        w = int(w)
        adj.setdefault(a, []).append((b, w))
        adj.setdefault(b, []).append((a, w))
    if start == goal:
        return 0
    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float('inf')):
            continue
        if u == goal:
            return d
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1

def solve(text):
    balance = 0
    rejected = 0
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 2 or parts[0] not in ("deposit", "withdraw") or not parts[1].isdigit():
            rejected += 1
            continue
        n = int(parts[1])
        if n <= 0:
            rejected += 1
            continue
        if parts[0] == "deposit":
            balance += n
        else:
            if balance >= n:
                balance -= n
            else:
                rejected += 1
    return f"{balance} {rejected}"
